<script lang="ts">
  import type { Snippet } from 'svelte'; import { cn } from '../../utils.js'; import { useQuestionContext } from './context.svelte.js'; let { class: className = '', children, disabled = false, ...rest }: { class?: string; children?: Snippet<[boolean]>; disabled?: boolean; [key: string]: unknown } = $props(); const context = useQuestionContext(); const hasResponse = $derived(context.value.selectedValues.length > 0 || context.value.text.trim().length > 0); const unavailable = $derived(context.disabled || disabled || context.busy || !hasResponse);
</script>
<button type="submit" class={cn('inline-flex min-h-9 items-center justify-center rounded-md border border-transparent bg-primary px-3 py-2 text-sm text-primary-foreground hover:opacity-90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring disabled:opacity-50', className)} disabled={unavailable} {...rest}>{#if children}{@render children(context.busy)}{:else}{context.busy ? 'Submitting...' : 'Submit'}{/if}</button>
